cases.script:
awk_cmd() { if [[ $(type -t awk) == builtin ]]; then awk "$@"; else gawk "$@"; fi; }
printf '%s\n' 'red' 'blue' > side
awk_cmd 'BEGIN { rc = (getline first < "side"); print rc, first; rc = (getline second < "side"); print rc, second; rc = (getline third < "side"); print rc; close("side") }'

awk_cmd() { if [[ $(type -t awk) == builtin ]]; then awk "$@"; else gawk "$@"; fi; }
printf '%s\n' 'alpha' 'beta' > input
awk_cmd 'BEGIN { print "header" > "report"; print "intro" >> "report" } { print NR, $0 >> "report"; print $0 } END { print "count", NR >> "report" }' input

awk_cmd() { if [[ $(type -t awk) == builtin ]]; then awk "$@"; else gawk "$@"; fi; }
printf '%s\n' 'first' 'second' > records
awk_cmd '{ if (NR == 1) FNR = 40; print NR, FNR }' records
